class RequestContextElement(val ctx: RequestContext) :
    AbstractCoroutineContextElement(RequestContextElement) {
    companion object Key : CoroutineContext.Key<RequestContextElement>
}

suspend fun requestContext(): RequestContext =
    coroutineContext[RequestContextElement]?.ctx
        ?: error("RequestContextElement missing from the coroutine context")
